use pyo3::prelude::*;
use pyo3::types::PyBytes;
use zstd::stream::CStream;

fn compress_data(py: Python, cctx: &CStream, source: &[u8]) -> PyResult<Py<PyBytes>> {
    let data = py.allow_threads(|| cctx.compress(source)).or_else(|msg| {
        Err(ZstdError::from_message(
