function generateHTMLTable(array $data): string {
    // Your implementation here
}
```

For example, given the following input array:
```php
$data = [
    'رقم التسجيل' => ['1', '2', '3'],
    'إسم الكابتن' => ['Ahmed', 'Sara', 'Mohammed'],
    'الجنسية' => ['Egyptian', 'Lebanese', 'Emirati'],
    'رقم الهاتف' => ['123456', '789012', '345678']
];
```

The function should generate the following HTML table:
```html
<table>
    <tr class='thead-dark'>
        <th>رقم التسجيل</th>
        <th>إسم الكابتن</th>
        <th>الجنسية</th>
        <th>رقم الهاتف</th>
    </tr>
    <tr>
        <td>1</td>
        <td>Ahmed</td>
        <td>Egyptian</td>
        <td>123456</td>
    </tr>
    <tr>
        <td>2</td>
        <td>Sara</td>
        <td>Lebanese</td>
        <td>789012</td>
    </tr>
    <tr>
        <td>3</td>
        <td>Mohammed</td>
        <td>Emirati</td>
        <td>345678</td>
    </tr>
</table>
```

### Solution:
```php
function generateHTMLTable(array $data): string {
    $output = '<table>';
    $output .= '<tr class=\'thead-dark\'>';
    foreach (array_keys($data) as $header) {
        $output .= "<th>$header</th>";
    }
    $output .= '</tr>';

    $numRows = count(reset($data));
    for ($i = 0; $i < $numRows; $i++) {
        $output .= '<tr>';
        foreach ($data as $column) {
            $output .= "<td>{$column[$i]}</td>";
        }
        $output .= '</tr>';
    }

    $output .= '</table>';
    return $output;
}

// Example usage
