### Solution:
```rust
use proc_macro::TokenStream;
use quote::quote;

fn process_template(input: TokenStream) -> TokenStream {
    let input_str = input.to_string();
    let transformed_html = format!("<!DOCTYPE html><html><head></head><body>{}</body></html>", input_str);
    let output = quote! { #transformed_html };
    output.into()
}
```

