function copyVideoSections(localDescription, remoteDescription, videosToReceive) {
  const isOffer = localDescription.includes('type=offer');
  const isAnswer = remoteDescription.includes('type=answer');
  const hasVideoInLocal = localDescription.includes('m=video');
  const hasNoVideoInRemote = !remoteDescription.includes('m=video');
  const hasVideosToReceive = videosToReceive.length > 0;

  return isOffer && isAnswer && hasVideoInLocal && hasNoVideoInRemote && hasVideosToReceive;
}
