### Solution:
```typescript
import { map } from './map.js'
import { isParent } from './is.js'

// Assume reverseArray is a built-in function that reverses the order of elements in an array
function reverseArray<T>(arr: T[]): T[] {
  return arr.reverse();
}

export function reverse(root: LHAST.Root): LHAST.Root {
  return map(
    root,
    node => {
      if (isParent(node)) {
        return {
          ...node,
          children: reverseArray(node.children)
        };
      }
      return node;
    }
  );
}
```
In the solution, the `reverse` function uses the `map` function to traverse the LHAST tree and apply the reversal logic to each parent node. If the current node is a parent node (determined using the `isParent` function), the order of its children is reversed using the `reverseArray` function. The modified tree with reversed children is then returned as the result.

