### Solution:
```python
def filter_profiles(profiles: list) -> list:
    filtered_profiles = []
    for profile in profiles:
        if profile["verified"] and profile["location"].strip() != "" and (profile["media_result"]["likes"] > 1000 or profile["media_result"]["shares"] > 1000):
            filtered_profiles.append(profile)
    return filtered_profiles
