    '<?php echo Yii::app()->theme->baseUrl;?>/assets/js/jquery-ui.min.js',
    '<?php echo Yii::app()->theme->baseUrl;?>/assets/css/style.css',
    '<?php echo Yii::app()->theme->baseUrl;?>/assets/js/custom.js',
    '<?php echo Yii::app()->theme->baseUrl;?>/assets/images/logo.png',
];
var_dump(extractBaseUrls($filePaths)); // Output: ['Yii::app()->theme->baseUrl']
```

The `extractBaseUrls` function iterates through the file paths, uses a regular expression to extract the base URL enclosed within the PHP echo statement, and then returns the unique base URLs as an array.

