// Output: '2/28/14 13:2:10 PM'
```

### Solution:
```javascript
function formatDateTime(dateTimeString, formatFrom, formatTo) {
  const date = new Date(dateTimeString);
  let hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();
  const amPm = hours >= 12 ? 'PM' : 'AM';

  if (formatFrom === 'dateTimeUsShortAmPm') {
    hours = hours % 12 || 12; // Convert 0 to 12 for 12-hour format
  } else if (formatFrom === 'dateTimeUsShortAM_PM') {
    hours = hours.toString().padStart(2, '0'); // Convert to 24-hour format
  }

  if (formatTo === 'dateTimeUsShortAmPm') {
    return `${date.getMonth() + 1}/${date.getDate()}/${date.getFullYear().toString().slice(-2)} ${hours}:${minutes}:${seconds} ${amPm}`;
  } else if (formatTo === 'dateTimeUsShortAM_PM') {
    return `${date.getMonth() + 1}/${date.getDate()}/${date.getFullYear().toString().slice(-2)} ${hours}:${minutes}:${seconds} ${amPm}`;
  }
}

// Test the function
console.log(formatDateTime('2/28/14 1:2:10 pm', 'dateTimeUsShortAmPm', 'dateTimeUsShortAM_PM'));
// Output: '2/28/14 13:2:10 PM'
```

