```cpp
#include <sstream>
#include <iomanip>

namespace phosphor
{
    namespace smbios
    {
        std::string System::uUID(std::string value)
        {
            uint8_t* dataIn = storage;
            dataIn = getSMBIOSTypePtr(dataIn, systemType);
