### Solution:
```javascript
function extractVersions(input) {
  const versionRegex = /\b(\d+\.\d+\.\d+)\b/g; // Regular expression to match semantic versioning format
  const versions = input.match(versionRegex); // Extract version numbers from the input string using the regex
  return versions || []; // Return the extracted version numbers or an empty array if none are found
