use Illuminate\Http\JsonResponse;

function handleException(\Exception $exception): JsonResponse
{
    $statusCode = 500;
    $message = $exception->getMessage();

    if ($message === "Unauthorized") {
        $statusCode = 401;
    } elseif ($message === "Not Found") {
        $statusCode = 404;
    }

    return response()->json([
