### Solution:
```javascript
function parseSVGPath(pathString) {
  const commands = pathString.match(/[MLHVCSZ]/g) || [];
  const uniqueCoordinates = new Set(pathString.match(/-?\d+(\.\d+)?/g));

  return {
    totalCommands: commands.length,
    commandCounts: countCommands(commands),
    uniqueCoordinates: uniqueCoordinates.size
  };
}

function countCommands(commands) {
