### Solution:
```rust
use std::time::Duration;
use actix_web::rt;
use tokio::time::{interval, Duration as TokioDuration};

fn schedule_task<F>(task_fn: F, interval: Duration) -> tokio::task::JoinHandle<()>
where
    F: Fn() + Send + 'static,
{
    let interval = interval;
    let task_fn = tokio::task::spawn(async move {
        let mut task = interval_at(Instant::now(), interval.to_std().expect("can't spawn on a negative interval"));
        loop {
            task_fn();
            task.tick().await;
        }
    });
    task_fn
}
```

In this solution, the `schedule_task` function takes a closure `task_fn` and a `Duration` representing the interval at which the task should be executed. It then uses `tokio::task::spawn` to spawn an asynchronous task that runs the `task_fn` at regular intervals specified by the `interval`. The task runs in an infinite loop, executing the `task_fn` and then waiting for the specified interval using `task.tick().await`. The returned `JoinHandle` allows the scheduled task to be canceled by dropping it.

