### Solution:
```typescript
import * as fs from 'fs';

function getExportedControllers(filePath: string): string[] {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const exportRegex = /export \* from '(.+?)';/g;
  const matches = fileContent.match(exportRegex);
  if (matches) {
    return matches.map(match => match.match(/'(.+?)'/)![1]);
  }
  return [];
}

