    while True:
        user_input = input("Enter your choice (rock, paper, scissors) or 'exit' to quit: ")
        if user_input.lower() == 'exit':
            sys.exit(0)
        elif user_input.lower() in ['rock', 'paper', 'scissors']:
            return user_input.lower()
        else:
            print("Invalid choice. Please enter rock, paper, or scissors.")

def get_computer_choice():
