    // Your implementation here
}
```

### Solution:
```rust
use sodiumoxide::crypto::box_::{PublicKey, SecretKey, gen_keypair, gen_nonce, Nonce, open, seal};

fn encrypt_message(message: &str, nonce: &[u8], sender_public_key: &[u8], receiver_private_key: &[u8]) -> Vec<u8> {
    // Convert keys to PublicKey and SecretKey types
    let sender_public_key = PublicKey::from_slice(sender_public_key).unwrap();
    let receiver_private_key = SecretKey::from_slice(receiver_private_key).unwrap();

    // Generate a nonce
    let sodium_nonce = Nonce::from_slice(nonce).unwrap();

    // Encrypt the message using crypto_box
    let encrypted = seal(message.as_bytes(), &sodium_nonce, &sender_public_key, &receiver_private_key);

    encrypted
}
```

