### Solution:
```cpp
#include <iostream>
#include <vector>

std::vector<int> customRandom(int seed, int a, int c, int m) {
    std::vector<int> randomSequence;
    int current = seed;
    for (int i = 0; i < 10; ++i) {
        current = (a * current + c) % m;
        randomSequence.push_back(current);
    }
    return randomSequence;
}

int main() {
