### Solution:
```php
function convertFileSizeToBytes($str) {
    $units = [
        'B' => 1,
        'kB' => 1024,
        'MB' => 1024 * 1024,
        'GB' => 1024 * 1024 * 1024,
        'TB' => 1024 * 1024 * 1024 * 1024,
    ];

    preg_match('/(\d+)\s*(\w+)/', $str, $matches);
    $size = (int)$matches[1];
    $unit = $matches[2];

