    if 'This is a test.' in content_before_test:
        remove_file('html/index.html')
        append_to_file('html/index.html', 'This is a hotcode test.')

    content_after_test = retrieve_file_content('b--hotcode.dork')
    if 'This is a test.' in content_after_test:
        remove_file('html/index.html')
        append_to_file('html/index.html', 'This is a test.')

