public func performLayout(inOrigin origin: CGPoint, width: CGFloat) -> CGFloat {
    // Create horizontal bounds using the provided origin and width
    let horizontalBounds = CGRect(origin: origin, size: CGSize(width: width, height: 0))

    // Calculate the horizontal position and width of the component using the horizontalLayout function
    let (x1, selfWidth) = horizontalLayout(rule: h, inBounds: horizontalBounds)

    // Calculate the absolute position of the component within the layout area
    let selfX = origin.x + x1
    let selfY = origin.y + top

    // Calculate the subcomponent's origin based on the relative flag
    let subOrigin = relative ? CGPoint(x: 0, y: 0) : CGPoint(x: selfX, y: selfY)

    // Recursively calculate the total height occupied by the subcomponent
    let subTotalHeight = sub.performLayout(inOrigin: subOrigin, width: selfWidth)

    // Set the height of the current component to be equal to the total height occupied by the subcomponent
    let selfHeight = subTotalHeight

    // Return the total height occupied by the current component and its subcomponent
    return selfHeight
}
```

